import { createAgUiEncoderState, finalizeAgUiEvents, mapRuntimeStreamEventToAgUiEvents, } from "./encoder.js";
/** Create AG-UI chunk encoder bridge. */
export function createAgUiChunkEncoderBridge(options) {
    const state = createAgUiEncoderState(options.timing ?? {});
    return {
        state,
        timingState: state,
        encode: (chunk) => options.getRuntimeEvents(chunk).flatMap((event) => mapRuntimeStreamEventToAgUiEvents(state, event)),
        finalize: (response) => finalizeAgUiEvents(state, response),
    };
}
